from concurrent.futures import ThreadPoolExecutor

prices = {"soup": 4.5, "tea": 1.5}
totals = []

def bill(dish, qty):
    totals.append(prices[dish] * qty)

with ThreadPoolExecutor() as pool:
    for dish, qty in [("soup", 2), ("toast", 1), ("tea", 2)]:
        pool.submit(bill, dish, qty)
print("takings:", sum(totals))

