import threading

count = 0

def add_many():
    global count
    for _ in range(100_000):
        count += 1          # read, add, write: no lock!

workers = [threading.Thread(target=add_many) for _ in range(4)]
for w in workers:
    w.start()
for w in workers:
    w.join()
print("expected 400000, got", count)

