import pickle

order = {"dish": "soup", "qty": 2}
blob = pickle.dumps(order)                # objects -> bytes
print(type(blob).__name__, "of length", len(blob))
print(pickle.loads(blob))                 # bytes -> objects

class Trap:
    def __reduce__(self):                 # "to rebuild me, call..."
        return (print, ("!!! loading this ran its maker's code",))

evil = pickle.dumps(Trap())
pickle.loads(evil)                        # just LOADING runs it

